(function(){
"use strict";
const oldExact=[{"q":"Macroeconomics is the study of the following issues, except for","opts":["the inflation rate rises.","the popularity of the incumbent president rises.","incomes fall.","the unemployment rate falls."],"ans":1,"topic":"Micro vs Macro","why":"Inflation, unemployment, and aggregate income are macroeconomic issues; the popularity of an incumbent president is not the macroeconomic issue tested here."},{"q":"The total income of everyone in the economy adjusted for the level of base year prices is called","opts":["an inflation.","a recession.","a business fluctuation.","real GDP."],"ans":3,"topic":"Nominal vs Real GDP","why":"Real GDP values aggregate output/income using base-year prices, removing price-level changes."},{"q":"Macroeconomics does not try to answer the question of","opts":["why do some countries have high rates of inflation.","what causes recessions and depressions.","what is the rate of return on education.","why do some countries experience rapid growth."],"ans":2,"topic":"Micro vs Macro","why":"The rate of return on an individual's education is a microeconomic question; inflation, recessions, and national growth are macroeconomic."},{"q":"A measure of how fast the general level of prices is rising is called the","opts":["inflation rate.","growth rate of real GDP.","unemployment rate.","market-clearing rate."],"ans":0,"topic":"CPI & Inflation","why":"The inflation rate measures the rate of increase in the general price level."},{"q":"A farmer raises free-range chickens, which he sells to a company for $1,000. That company sells the \"processed\" chickens to a grocery store for $1,600, which in turn produces roasted chickens which are sold to the public for $2,400. Based on this information, the value of total output is equal to","opts":["$2,400","$1,400","$1,600","$4,000","$5,000"],"ans":0,"topic":"Final vs Intermediate Goods","why":"Counting the final roasted chickens at $2,400 avoids double counting intermediate transactions."},{"q":"In macroeconomics, the term \"capital goods\" refers to","opts":["stocks and bonds.","man-made factors of production, such as tools, machines, and factory buildings.","the financial resources necessary to start a firm.","all factors of production.","money."],"ans":1,"topic":"Physical vs Financial Capital","why":"Capital goods are produced physical resources used to produce other goods and services."},{"q":"The value of the gross domestic product in 2000, in terms of 1990 prices, was","opts":["1,200","600","1,000","700","1,300"],"ans":1,"topic":"Nominal vs Real GDP","why":"Using the old exam table, nominal GDP in 2000 is 1,200 and the 1990-base GDP deflator is 200, so real GDP = 1,200/200×100 = 600."},{"q":"If 2000 were made the base year for the GDP price deflator index, the value of the index number of 1990 (rounded to the nearest whole number) would be","opts":["256","50","212","142","zero"],"ans":1,"topic":"GDP Deflator","why":"Rebasing the deflator makes 2000 equal 100; with the old table's relative price levels, 1990 becomes 50."},{"q":"Which of the following is true if real GDP in Year 1 is $5,000 and in Year 2 is $5,200?","opts":["Output change is uncertain.","The economy is experiencing a recession.","Output has decreased by 4 percent.","The economy is experiencing 4 percent inflation.","Output has increased by 4 percent."],"ans":4,"topic":"Economic Growth Concept","why":"(5,200−5,000)/5,000 = 0.04, so real output increased by 4 percent."},{"q":"Of the following, which is the best example of structural unemployment?","opts":["A computer programmer who quits her job to move to a warmer climate.","A construction worker who loses his job in the winter.","An auto worker who loses her job during a recession.","A steel worker who is replaced by a robot.","A toy maker who worked for a company that closed because consumer did not buy its toys."],"ans":3,"topic":"Types of Unemployment","why":"Replacement by technology creates a skills/job mismatch, which is structural unemployment."},{"q":"Using the Rule of 70, if the country of Flowerdom’s current growth rate of real GDP per person was 7 percent a year, how long would it take the country’s real GDP per person to double?","opts":["1 year","2 years","10 years","49 years","70 years"],"ans":2,"topic":"Rule of 70","why":"Rule of 70: doubling time ≈ 70/7 = 10 years."},{"q":"Which of the following is NOT an important factor affecting growth in labor productivity?","opts":["the saving rate","the speed with which prices fall","the growth rate of physical capital","the growth rate of labor productivity","the growth of technology and innovation"],"ans":1,"topic":"Drivers of Productivity","why":"The speed at which prices fall is not a productivity-growth driver in the lecture framework."},{"q":"All of the following contribute to labor productivity growth EXCEPT:","opts":["population growth.","physical capital growth.","human capital growth.","technological advancements.","innovation development."],"ans":0,"topic":"Drivers of Productivity","why":"Population growth increases labor quantity; by itself it does not raise output per hour of labor."},{"q":"Which of the following is associated with classical growth theory?\nI. Growth in real GDP can continue indefinitely.\nII. Technological growth increases as the population grows.\nIII. Population explosions bring real GDP per person back to subsistence levels.","opts":["I","II","III","I and II","I and III"],"ans":2,"topic":"Classical Growth Theory","why":"The classical mechanism emphasizes population expansion pushing real GDP per person back toward subsistence."},{"q":"In neoclassical growth theory, technological change ________.","opts":["occurs by chance","is influenced by population growth","is influenced by the rate of economic growth","occurs at a steady rate","is influenced by the government"],"ans":0,"topic":"Neoclassical Growth Theory","why":"In the lecture's neoclassical treatment, technological change is exogenous rather than explained by the model."},{"q":"An important foundation of the new growth theory is that","opts":["we will get more technological advances the more the government is involved in deciding which technology to pursue.","we will get more technological advances the greater the rewards people receive from making technological advances.","the growth rate of the capital stock is more important than the growth rate of new knowledge in generating economic growth.","improvements in labor productivity are poor measures of technological growth.","population growth remains the most influential factor to economic growth."],"ans":1,"topic":"New Growth Theory","why":"New Growth Theory emphasizes incentives and rewards that motivate discovery and innovation."},{"q":"In January 2011, Tim's Gyms, Inc. owned machines valued at $1 million. During the year, the market value of the machines fell by 10 percent. During 2011, Tim spent $200,000 on new machines. During 2011, Tim's net investment was","opts":["$1 million.","$300,000.","$200,000.","$100,000.","$1.1 million"],"ans":3,"topic":"Gross vs Net Investment","why":"Depreciation is $100,000; net investment = $200,000 gross investment − $100,000 depreciation = $100,000."},{"q":"Investment is financed by which of the following?\nI. Government spending.\nII. Household saving.\nIII. Borrowing from the rest of the world.","opts":["I, II, and III","I and II only","I and III only","II and III only","None of the above"],"ans":3,"topic":"Loanable Funds: Supply","why":"Household saving and borrowing from the rest of the world provide funds available for investment."},{"q":"As the ________ interest rate rises ________.","opts":["nominal; the demand for loanable funds curve shifts rightward","real; the demand for loanable funds curve shifts rightward","nominal; the demand for loanable funds curve shifts leftward","real; a movement occurs up along the demand for loanable funds curve","real; a movement occurs down along the demand for loanable funds curve"],"ans":3,"topic":"Loanable Funds: Demand","why":"The real interest rate is the price of loanable funds; a higher rate causes an upward movement along the existing demand curve."},{"q":"During a recession, firms decrease their profit expectations. As a result, there is a ________ shift of the ________ loanable funds curve.","opts":["rightward; supply of","leftward; demand for","rightward; demand for","rightward; supply of","leftward; demand for loanable funds curve and supply of"],"ans":1,"topic":"Loanable Funds: Demand","why":"Lower expected profit reduces planned investment, shifting demand for loanable funds left."}];
const legacyReview=[{"q":"Scarcity exists when:","opts":["society can satisfy every want","resources are limited relative to wants","all resources are unemployed","technology never changes"],"ans":1,"topic":"Scarcity","why":"Scarcity means limited resources cannot satisfy all wants."},{"q":"A vacation costs $2,000 and causes you to give up $750 of wages. The economic cost of the vacation is:","opts":["$750","$1,250","$2,000","$2,750"],"ans":3,"topic":"Opportunity Cost","why":"Economic cost includes the $2,000 explicit cost plus $750 forgone income."},{"q":"The term that emphasizes that choosing one alternative means giving up another is:","opts":["opportunity cost","accounting cost","utility cost","substitution cost"],"ans":0,"topic":"Opportunity Cost","why":"Opportunity cost captures the value of the next-best forgone alternative."},{"q":"The opportunity cost of an action is best defined as:","opts":["the sum of every rejected option","the highest-valued alternative given up","only the cash payment","the benefit minus the cash cost"],"ans":1,"topic":"Opportunity Cost","why":"The lecture uses the next-best alternative forgone."},{"q":"Economics is best described as the study of how people and societies:","opts":["eliminate all scarcity","make choices to cope with scarcity","use unlimited resources","guarantee equal outcomes"],"ans":1,"topic":"What is Economics?","why":"Economics studies choices under scarcity."},{"q":"Which statement is correct? I. Opportunity cost is the highest-valued alternative forgone. II. Wealth removes opportunity cost. III. Scarcity creates opportunity cost.","opts":["I only","I and II","I and III","I, II and III"],"ans":2,"topic":"Opportunity Cost","why":"I and III are consistent with scarcity and opportunity cost; wealth does not eliminate scarcity."},{"q":"Economic questions arise because people generally:","opts":["want more than they can get with available resources","have no wants","have unlimited resources","can always produce everything"],"ans":0,"topic":"Scarcity","why":"Wants exceed what limited resources can provide."},{"q":"In every economic system, resources are generally ________ while wants are ________.","opts":["limited; unlimited","unlimited; limited","limited; limited by law","unlimited; unlimited"],"ans":0,"topic":"Scarcity","why":"The scarcity problem comes from limited resources relative to broad/unlimited wants."},{"q":"Which household purchase counts as investment in GDP?","opts":["a newly constructed house","an imported used car","100 shares of stock","a government bond"],"ans":0,"topic":"GDP Components","why":"New residential construction is counted as investment."},{"q":"Which item is investment in the national income accounts?","opts":["construction of a new factory","purchase of an existing stock share","holding currency","purchase of a government bond"],"ans":0,"topic":"GDP Components","why":"New factory construction adds newly produced capital."},{"q":"A U.S. firm imports bananas for $1,000 and sells them domestically for $2,000. Holding the example's other details fixed, the contribution to U.S. GDP is:","opts":["$0","$1,000","$2,000","$3,000"],"ans":1,"topic":"GDP Components","why":"Consumption adds $2,000 while imports subtract $1,000, leaving $1,000 of domestic value added."},{"q":"Which expression matches the expenditure approach to GDP?","opts":["C + I + G + (X − M)","C + saving + taxes","wages + imports only","C + I + depreciation only"],"ans":0,"topic":"Expenditure Approach","why":"The expenditure approach is C + I + G + net exports."},{"q":"Real GDP differs from nominal GDP because real GDP:","opts":["uses base-year prices","includes only exports","excludes investment","always equals GDP per person"],"ans":0,"topic":"Nominal vs Real GDP","why":"Real GDP values production using constant/base-year prices."},{"q":"Which is a limitation of GDP as a quality-of-life measure?","opts":["It does not directly include the value of leisure.","It cannot measure production.","It always excludes government purchases.","It counts no market services."],"ans":0,"topic":"Uses & Limits of Real GDP","why":"Leisure and several nonmarket dimensions of welfare are not directly included in GDP."},{"q":"If nominal GDP is 1,200 and the GDP deflator is 200 (base = 100), real GDP is:","opts":["600","1,000","1,200","2,400"],"ans":0,"topic":"GDP Deflator","why":"Real GDP = nominal GDP / deflator × 100 = 600."},{"q":"A worker who loses a job because a robot replaces the worker's task is most clearly:","opts":["frictionally unemployed","seasonally unemployed","structurally unemployed","not in the labor force"],"ans":2,"topic":"Types of Unemployment","why":"Technology can create a mismatch between existing skills/jobs and available work."},{"q":"If real GDP rises from 5,000 to 5,200, the growth rate is:","opts":["2%","4%","5%","20%"],"ans":1,"topic":"Economic Growth Concept","why":"200/5,000 × 100 = 4%."},{"q":"At 7% annual growth, the Rule of 70 gives an approximate doubling time of:","opts":["7 years","10 years","14 years","70 years"],"ans":1,"topic":"Rule of 70","why":"70/7 = 10."},{"q":"Net investment equals:","opts":["gross investment plus depreciation","gross investment minus depreciation","depreciation minus gross investment","saving minus consumption"],"ans":1,"topic":"Gross vs Net Investment","why":"Net investment is gross investment less depreciation."},{"q":"If firms become less optimistic about future profits, demand for loanable funds will generally:","opts":["shift left","shift right","stay fixed while supply shifts left","move down because the real rate rose"],"ans":0,"topic":"Loanable Funds: Demand","why":"Lower expected profit reduces desired investment at each real interest rate."}];
const hardSource=[{"q":"Nominal GDP is 2,400 and the GDP deflator is 120. If population is 20, real GDP per person is:","opts":["80","100","120","2,000"],"ans":1,"topic":"Real GDP per Person","why":"Real GDP = 2,400/120×100 = 2,000; per person = 2,000/20 = 100."},{"q":"A final product sells for 3,000 after intermediate sales of 900 and 1,800. Using the final-goods method, GDP counts:","opts":["900","1,800","3,000","5,700"],"ans":2,"topic":"Final vs Intermediate Goods","why":"The final-goods method counts the final value once, avoiding double counting."},{"q":"A country has 96 employed people, 4 unemployed people actively seeking work, and 25 adults not in the labor force. Its unemployment rate is:","opts":["3.2%","4.0%","5.0%","20.0%"],"ans":1,"topic":"Labor Market Indicators","why":"Labor force = 96+4=100; unemployment rate = 4/100 = 4%."},{"q":"Real GDP grows 6% while population grows 2%. The lecture approximation implies real GDP per person grows about:","opts":["2%","4%","6%","8%"],"ans":1,"topic":"Real GDP per Person","why":"Per-person growth is approximately total real GDP growth minus population growth: 6%−2%=4%."},{"q":"A basket costs 500 in the base year and 575 this year. The CPI is 115, so the inflation rate from the base-year CPI of 100 is:","opts":["5%","15%","75%","115%"],"ans":1,"topic":"Constructing CPI","why":"(115−100)/100×100 = 15%."},{"q":"A new technology raises productivity, but rapid population growth then lowers capital and resources per worker until living standards return toward subsistence. This chain is:","opts":["Classical Growth Theory","Neoclassical Growth Theory","New Growth Theory","Ricardo–Barro"],"ans":0,"topic":"Classical Growth Theory","why":"This is the classical population-and-limited-resources mechanism."},{"q":"Which combination most directly raises labor productivity in the lecture framework?","opts":["More physical capital per hour, more human capital, and technological progress","Higher inflation, more population, and lower saving","Longer workweeks only","A higher nominal interest rate only"],"ans":0,"topic":"Drivers of Productivity","why":"Physical capital, human capital, and technology are the central productivity drivers."},{"q":"Gross investment is 450 while depreciation is 500. Net investment is:","opts":["−50","50","450","950"],"ans":0,"topic":"Gross vs Net Investment","why":"Net investment = 450−500 = −50, so the capital stock shrinks."},{"q":"Expected profit rises while the real interest rate initially stays unchanged. In the loanable-funds market, the first effect is:","opts":["a rightward shift of demand","a leftward shift of demand","a rightward shift of supply","a movement down the same demand curve"],"ans":0,"topic":"Loanable Funds: Demand","why":"Expected profit is a demand shifter; higher expected profit increases planned investment."},{"q":"A government budget deficit increases without a full Ricardo–Barro offset. The lecture's standard chain is:","opts":["DLF right → real interest rate up → private investment down","SLF right → real interest rate down → investment up","DLF left → real interest rate down → investment up","no market effect by definition"],"ans":0,"topic":"Crowding-Out Effect","why":"The standard deficit story raises demand for loanable funds, the real rate, and crowds out private investment."},{"q":"If consumers expect a good's future price to rise, the lecture's demand example predicts current demand will:","opts":["shift right","shift left","move down the same demand curve","not change"],"ans":0,"topic":"Demand Determinants","why":"Future-price expectations are a demand shifter; expected future price increases can raise current demand."},{"q":"A fall in an input price, with the good's own price unchanged, causes:","opts":["supply to shift right","supply to shift left","movement up the same supply curve","demand to shift right"],"ans":0,"topic":"Supply Determinants","why":"Lower production cost increases supply at each own price."},{"q":"At the current price, quantity demanded is 120 and quantity supplied is 90. The market has:","opts":["a shortage of 30","a surplus of 30","equilibrium","a shortage of 210"],"ans":0,"topic":"Surplus & Shortage","why":"Qd exceeds Qs by 30, so there is a shortage."},{"q":"An economy moves from a point inside its PPF to a point on the PPF without changing resources or technology. This represents:","opts":["greater productive efficiency","economic growth shifting the frontier","an unattainable outcome","higher inflation"],"ans":0,"topic":"PPF: Efficient / Inefficient","why":"Moving from inside to the frontier uses existing resources more efficiently; the frontier itself need not shift."},{"q":"A firm earns revenue of 900, explicit costs of 600, and has an implicit opportunity cost of 100. Its accounting profit and economic profit are:","opts":["300 and 200","200 and 300","300 and 300","200 and 200"],"ans":0,"topic":"Accounting vs Economic Profit","why":"Accounting profit = 900−600=300; economic profit = 900−600−100=200."},{"q":"If the price of a bond rises while its promised payments are unchanged, its yield generally:","opts":["falls","rises","becomes equal to inflation","becomes zero by definition"],"ans":0,"topic":"Interest Rates & Asset Prices","why":"Asset price and yield move inversely when promised payments are unchanged."},{"q":"Which transaction creates financial capital for a firm rather than physical capital itself?","opts":["The firm issues shares and receives funds.","The firm installs a new machine.","The firm builds a warehouse.","The firm buys a delivery truck."],"ans":0,"topic":"Physical vs Financial Capital","why":"Funds raised through financial markets are financial capital; machines/buildings/trucks are physical capital."},{"q":"If the CPI rises from 125 to 130, the inflation rate is:","opts":["4%","5%","25%","30%"],"ans":0,"topic":"CPI & Inflation","why":"(130−125)/125×100 = 4%."},{"q":"A discouraged worker stops looking for work. Other things equal, the measured labor force:","opts":["falls","rises","is unchanged","becomes equal to population"],"ans":0,"topic":"Employment vs Unemployment","why":"A person not actively seeking work is outside the labor force under the lecture definitions."},{"q":"New Growth Theory differs from the lecture's Neoclassical treatment mainly because New Growth Theory:","opts":["explains technological progress through choices, incentives, human capital, and discovery","assumes technology only arrives by chance","denies that knowledge matters","requires population to return income to subsistence"],"ans":0,"topic":"New Growth Theory","why":"New Growth Theory makes innovation and knowledge growth responsive to incentives and choices."}];
function cloneQ(q){return{q:q.q,opts:[...q.opts],ans:q.ans,topic:q.topic,why:q.why,source:q.source||""}}
function spread(pool,n){const out=[];if(!Array.isArray(pool)||!pool.length||n<=0)return out;for(let i=0;i<n;i++){const idx=Math.floor(i*pool.length/n);out.push(cloneQ(pool[Math.min(idx,pool.length-1)]))}return out}
function hashText(s){let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)}return h>>>0}
function mixAndGroup(items){return items.map((q,i)=>({q:cloneQ(q),k:(hashText(q.q)^Math.imul(i+1,2654435761))>>>0})).sort((a,b)=>a.k-b.k).map((x,i)=>Object.assign(x.q,{midtermGroup:"ABCD"[i%4]}))}
const reviewQuizMidterm=mixAndGroup([
  ...oldExact.filter((_,i)=>i%2===0),
  ...legacyReview,
  ...spread(reviewQuiz,10),
  ...spread(reviewQuizNext,10),
  ...spread(reviewQuizL2GDP,10),
  ...spread(reviewQuizL2UI,8),
  ...spread(reviewQuizL3,6),
  ...spread(reviewQuizL4,6)
]);
const masteryQuizMidterm=mixAndGroup([
  ...oldExact,
  ...hardSource,
  ...spread(masteryQuiz,8),
  ...spread(masteryQuizNext,8),
  ...spread(masteryQuizL2GDP,7),
  ...spread(masteryQuizL2UI,6),
  ...spread(masteryQuizL3,6),
  ...spread(masteryQuizL4,5)
]);
if(reviewQuizMidterm.length!==80||masteryQuizMidterm.length!==80)throw new Error("Midterm bank size mismatch");
quizSets.midterm={label:"EC214 — Midterm Mock Exam • 80Q"};
const readAlong=["s1","s9","s13","s17","s23"];
for(const g of "ABCD"){
  quizParts["midterm-"+g.toLowerCase()]={set:"midterm",pool:"midterm",group:g,label:"Part "+("ABCD".indexOf(g)+1)+" • Mixed Midterm "+g+" • 20Q",pages:"All current midterm lectures • topics scrambled",summaries:readAlong,topics:null};
}
quizParts["midterm-all"]={set:"midterm",pool:"midterm",group:null,label:"Cumulative • Midterm Mock Exam • 80Q",pages:"All current midterm lectures • full mixed bank",summaries:readAlong,topics:null};
const coreGetQuizFor=getQuizFor;
getQuizFor=function(part=quizPart,mode=quizMode){
  const meta=quizParts[part];
  if(meta&&meta.pool==="midterm"){
    const base=mode==="mastery"?masteryQuizMidterm:reviewQuizMidterm;
    return meta.group?base.filter(q=>q.midtermGroup===meta.group):base;
  }
  return coreGetQuizFor(part,mode);
};
const coreMakeOptionOrders=makeOptionOrders;
makeOptionOrders=function(qs){
  if(qs.every(q=>q.opts.length===4))return coreMakeOptionOrders(qs);
  return qs.map(q=>shuffledCopy(q.opts.map((_,i)=>i)));
};
function ensureLibraryItem(){
  const list=document.querySelector(".quiz-library-list");
  if(!list||list.querySelector('[data-quiz-set-item="midterm"]'))return;
  const li=document.createElement("li");
  li.className="quiz-library-item";
  li.dataset.quizSetItem="midterm";
  li.innerHTML='<a class="library-link" data-quiz-set-link="midterm" href="/d-study-app/quiz-midterm/">Midterm Mock Exam — 80Q • 4 mixed 20Q parts + cumulative →</a><span class="quiz-set-progress" data-quiz-progress="midterm">0/4 done</span>';
  list.appendChild(li);
}
ensureLibraryItem();
const coreApplyPathRoute=applyPathRoute;
applyPathRoute=function(){
  const p=location.pathname.replace(/\/+$/,"");
  if(p.endsWith("/quiz-midterm")){
    quizSet="midterm";
    if(!quizParts[quizPart]||quizParts[quizPart].set!=="midterm")quizPart="midterm-a";
    quizSession=loadQuizDraft(quizMode,quizPart);
    renderQuizSetButtons();renderQuizPartButtons();renderQuiz();switchTab("quiz");return;
  }
  return coreApplyPathRoute();
};
const footer=document.getElementById("appVersionLabel");if(footer)footer.textContent="D Study App v13.4";
const subjectEyebrow=document.querySelector(".subject-topbar .eyebrow");if(subjectEyebrow)subjectEyebrow.textContent="D Study App • v13.4";
if(activeUser&&state){renderQuizLibraryProgress();if(activeSubject)applyPathRoute()}
})();